// Wikipedia and Wikisource: the exact article for a sage, and the Hebrew Wikisource
// author page ("מחבר:...") where the texts he wrote are collected.
// public/data-wikipedia.json is generated by scripts/build_wikidata_links.py from
// Wikidata, keyed by sage id. Bundled at build time, so a sage page makes no request
// to Wikimedia until the reader clicks through.
import wikiData from '../public/data-wikipedia.json'
import type { SefariaEntry } from './sefaria'

export interface WikiEntry {
  /** The roster label this entry was matched against; guards against ids drifting. */
  label: string
  /** Wikidata item, e.g. "Q42". */
  qid: string
  /** "years": birth/death years agree with the roster. "name": no years to compare, the Hebrew label is exactly his name. */
  how: 'years' | 'name'
  /** Hebrew Wikipedia article title. */
  he?: string
  /** English Wikipedia article title. */
  en?: string
  /** Hebrew Wikisource author page title. */
  wikisource?: string
}

const entries = (wikiData as unknown as { sages: Record<string, WikiEntry> }).sages

export function getWiki(sageId: string): WikiEntry | undefined {
  return entries[sageId]
}

export function wikiEntries(): Array<[string, WikiEntry]> {
  return Object.entries(entries)
}

export interface WikiLinks {
  he?: string
  en?: string
  wikisource?: string
}

/**
 * The articles to link for a sage. Wikidata's match (checked against his years) is
 * preferred; where there is none, the Wikipedia titles Sefaria holds for the same
 * author fill in, so a sage Sefaria knows is not left with a search link.
 */
export function wikiLinks(sageId: string, sefaria?: SefariaEntry): WikiLinks {
  const w = entries[sageId]
  return {
    he: w?.he ?? sefaria?.wiki?.he,
    en: w?.en ?? sefaria?.wiki?.en,
    wikisource: w?.wikisource,
  }
}

const page = (host: string, title: string) =>
  `https://${host}/wiki/${encodeURIComponent(title.replace(/ /g, '_')).replace(/%3A/gi, ':')}`

export const wikipediaUrl = (lang: 'he' | 'en', title: string) => page(`${lang}.wikipedia.org`, title)
export const wikisourceUrl = (title: string) => page('he.wikisource.org', title)
